def comb_sort(arr):
    import math
    gap = len(arr)
    shrink = 1.3
    while gap > 1:
        gap = int(gap / shrink)
        if gap == 0:
            gap = 1
        i = 0
        while i + gap < len(arr):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
            i += 1
    return arr
